#!/usr/bin/env python3
"""Generate the "Update or remove …" issue forms from data/*.json.

Issue-form dropdowns are static YAML, so this rewrites the forms whenever the
data changes (run by issue-to-data.yml and edit-forms.yml). Each form lists
every current entry in a dropdown, using the labels issue_to_data.py matches
on, followed by that type's own edit fields (TYPES[kind]["edit_inputs"]).
"""
import json

from issue_to_data import EDIT_FIELDS, ROLES, ROOT, TYPES, entry_labels

OUT = ROOT / ".github" / "ISSUE_TEMPLATE"
FORMS = {"speaking": ("update-speaking-event.yml", "🎤"), "project": ("update-project.yml", "🚀"), "testimonial": ("update-testimonial.yml", "💬")}


def q(s):
    """Quote a string for YAML (JSON strings are valid YAML)."""
    return json.dumps(s, ensure_ascii=False)


def field(widget, id_, label, help_):
    lines = []
    if widget in ("text", "list"):
        lines += ["  - type: input", f"    id: {id_}", "    attributes:", f"      label: {q(label)}"]
    elif widget == "textarea":
        lines += ["  - type: textarea", f"    id: {id_}", "    attributes:", f"      label: {q(label)}"]
    elif widget == "roles":
        lines += ["  - type: checkboxes", f"    id: {id_}", "    attributes:", f"      label: {q(label)}", "      options:"]
        lines += [f"        - label: {q(r)}" for r in ROLES]
    elif widget in ("bool", "stars"):
        options = ["Keep", "Yes", "No"] if widget == "bool" else ["Keep", "5", "4", "3", "2", "1"]
        lines += ["  - type: dropdown", f"    id: {id_}", "    attributes:", f"      label: {q(label)}", "      options:"]
        lines += [f"        - {q(o)}" for o in options]
        lines += ["      default: 0"]
    if help_:
        lines.append(f"      description: {q(help_)}")
    return lines


def render(kind):
    t, noun = TYPES[kind], TYPES[kind]["noun"]
    filename, emoji = FORMS[kind]
    dropdown = next(label for label, k in EDIT_FIELDS.items() if k == kind)
    data = json.loads((ROOT / t["path"]).read_text())
    lines = [
        f"# Generated by .github/scripts/build_edit_forms.py from {t['path']} — don't edit by hand.",
        f"name: {q(f'{emoji} Update or remove {noun}')}",
        f"description: {q(f'Pick an existing {noun} to change or delete — the site updates automatically.')}",
        f"title: {q(f'[edit] {noun}')}",
        'labels: ["data:edit"]',
        "body:",
        "  - type: markdown",
        "    attributes:",
        f"      value: {q('Pick the entry, then fill in **only what should change** — blank fields keep their current value. Only issues opened by the repo owner are processed.')}",
        "  - type: dropdown",
        "    id: entry",
        "    attributes:",
        f"      label: {q(dropdown)}",
        f"      description: {q(f'{len(data)} entries')}",
        "      options:",
        *[f"        - {q(label)}" for label in entry_labels(kind, data)],
        "    validations:",
        "      required: true",
        "  - type: dropdown",
        "    id: action",
        "    attributes:",
        "      label: Action",
        "      description: Remove deletes the whole entry and ignores the fields below",
        "      options:",
        "        - Update",
        "        - Remove",
        "      default: 0",
        "    validations:",
        "      required: true",
    ]
    for i, (label, key, widget, help_) in enumerate(t["edit_inputs"]):
        lines += field(widget, f"new_{i}", label, help_)
    if kind == "speaking":
        lines += [
            "  - type: textarea",
            "    id: add_resources",
            "    attributes:",
            "      label: Add resources",
            f"      description: {q('One per line: `type | url` or `type | label | url`. Types: event, slides, code, demo, video, blog. You can drag a PDF in for slides.')}",
            "      placeholder: |",
            "        video | https://youtube.com/watch?v=...",
            "        blog | My write-up | https://medium.com/@nomadicmehul/...",
            "  - type: input",
            "    id: remove_resources",
            "    attributes:",
            "      label: Remove resources",
            f"      description: {q('Comma-separated types to remove, e.g. `slides, demo`')}",
        ]
    (OUT / filename).write_text("\n".join(lines) + "\n")
    return filename, len(data)


def main():
    for kind in FORMS:
        filename, n = render(kind)
        print(f"{filename}: {n} entries")


if __name__ == "__main__":
    main()
